import { useCallback, useEffect, useRef, useState } from 'react';
import { batch, useStore } from 'react-redux';

import { Note, notesActions } from 'app/services/NotesService';
import { selectSettings } from 'app/services/SettingsService';
import {
  Timbre,
  loadSound,
  resumeAudio,
} from 'app/services/SynthesizerService';
import { RootState } from 'app/services/types';

import { parseMidiMessage } from './messages';
import {
  MidiAccess,
  MidiInputPort,
  MidiMessageEvent,
  MidiNavigator,
} from './types';

type ActiveNote = {
  note: Note;
  timbre: Timbre;
  source: string;
  recorded: boolean;
  held: boolean;
  channel: number;
};

export const useMidiInput = () => {
  const store = useStore<RootState>();
  const [access, setAccess] = useState<MidiAccess>();
  const [inputs, setInputs] = useState<MidiInputPort[]>([]);
  const [inputId, setInputId] = useState('');
  const [connecting, setConnecting] = useState(false);
  const [error, setError] = useState('');
  const pending = useRef(0);
  const release = useRef(() => {});
  const supported =
    typeof (navigator as MidiNavigator).requestMIDIAccess === 'function';
  const input = inputs.find(port => port.id === inputId);

  useEffect(
    () => () => {
      pending.current++;
    },
    [],
  );

  const connect = async () => {
    const request = (navigator as MidiNavigator).requestMIDIAccess;
    if (!request || connecting) return;
    const id = ++pending.current;
    setConnecting(true);
    setError('');
    try {
      // Resume audio inside the button gesture, before permission or I/O awaits.
      const audioReady = resumeAudio();
      const midiReady = request.call(navigator, { sysex: false });
      const [midi] = await Promise.all([
        midiReady,
        audioReady,
        loadSound(selectSettings(store.getState()).timbre),
      ]);
      if (id === pending.current) setAccess(midi);
    } catch (cause) {
      if (id !== pending.current) return;
      setError(
        cause instanceof Error &&
          ['NotAllowedError', 'SecurityError'].includes(cause.name)
          ? 'Доступ к MIDI запрещён. Разрешите его в настройках сайта и повторите подключение.'
          : 'Не удалось подключить MIDI или загрузить звук. Повторите подключение.',
      );
    } finally {
      if (id === pending.current) setConnecting(false);
    }
  };

  const disconnect = () => {
    pending.current++;
    release.current();
    setAccess(undefined);
    setInputs([]);
    setInputId('');
    setConnecting(false);
    setError('');
  };

  const selectInput = (id: string) => {
    release.current();
    setError('');
    setInputId(id);
  };

  useEffect(() => {
    if (!access) return;
    const refresh = () => {
      const ports: MidiInputPort[] = [];
      access.inputs.forEach(port => {
        if (port.state === 'connected') ports.push(port);
      });
      setInputs(ports);
      setInputId(previous =>
        ports.some(port => port.id === previous)
          ? previous
          : ports[0]?.id ?? '',
      );
    };
    refresh();
    access.addEventListener('statechange', refresh);
    return () => access.removeEventListener('statechange', refresh);
  }, [access]);

  const stopNotes = useCallback(() => release.current(), []);

  useEffect(() => {
    if (!input) return;
    const notes = new Map<string, ActiveNote>();
    const sustained = new Set<number>();
    let focused = true;
    let active = true;
    const end = (key: string) => {
      const note = notes.get(key);
      if (!note) return;
      notes.delete(key);
      batch(() => {
        store.dispatch(notesActions.muteNote(note));
        if (note.recorded)
          store.dispatch(notesActions.logEndingNote(note.note));
      });
    };
    const reset = () => {
      sustained.clear();
      Array.from(notes.keys()).forEach(end);
    };
    release.current = reset;
    const onMessage = ({ data }: MidiMessageEvent) => {
      if (!active || !focused || document.hidden) return;
      const message = parseMidiMessage(data);
      if (!message) return;
      const { channel } = message;
      if (message.type === 'sustain' || message.type === 'resetControllers') {
        if (message.down) sustained.add(channel);
        else {
          sustained.delete(channel);
          notes.forEach((note, key) => {
            if (note.channel === channel && !note.held) end(key);
          });
        }
        return;
      }
      if (message.type === 'allNotesOff') {
        sustained.delete(channel);
        notes.forEach((note, key) => {
          if (note.channel === channel) end(key);
        });
        return;
      }
      if (!('number' in message)) return;
      const key = `${channel}:${message.number}`;
      if (message.type === 'noteOff') {
        const note = notes.get(key);
        if (note && sustained.has(channel)) note.held = false;
        else end(key);
        return;
      }
      if (notes.get(key)?.held) return;
      end(key);
      const { timbre, isRecording } = selectSettings(store.getState());
      const note: ActiveNote = {
        note: message.note,
        timbre,
        source: `midi:${input.id}:${key}`,
        channel,
        held: true,
        recorded: isRecording,
      };
      notes.set(key, note);
      batch(() => {
        store.dispatch(notesActions.playNote(note));
        if (isRecording)
          store.dispatch(notesActions.logStartingNote(note.note));
      });
    };
    const blur = () => {
      focused = false;
      reset();
    };
    const focus = () => {
      focused = true;
    };
    const visibility = () => {
      if (document.hidden) reset();
    };
    input.addEventListener('midimessage', onMessage);
    input.open().catch(() => {
      if (active) {
        reset();
        setAccess(undefined);
        setInputs([]);
        setInputId('');
        setError('Не удалось открыть MIDI-устройство. Повторите подключение.');
      }
    });
    window.addEventListener('blur', blur);
    window.addEventListener('focus', focus);
    document.addEventListener('visibilitychange', visibility);
    return () => {
      active = false;
      reset();
      release.current = () => {};
      input.removeEventListener('midimessage', onMessage);
      input.close().catch(() => {});
      window.removeEventListener('blur', blur);
      window.removeEventListener('focus', focus);
      document.removeEventListener('visibilitychange', visibility);
    };
  }, [input, store]);

  return {
    supported,
    connected: !!access,
    connecting,
    inputs,
    inputId,
    error,
    connect,
    disconnect,
    selectInput,
    stopNotes,
  };
};
