import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import { Note } from 'app/services/NotesService/types';

import { Subdivision, getNormalizationOptions } from './normalization';
import { getNoteDuration } from './timing';
import { Melody, NoteInMelody } from './types';

export type NoteEditMode = 'move' | 'resize-start' | 'resize-end';
export const MAX_NOTE_PITCH = 107; // C0–B8, matching musical input.
export const notePitch = (note: Note) =>
  Number(note.slice(-1)) * 12 +
  chromaticNotes.indexOf(note.slice(0, -1) as typeof chromaticNotes[number]);
export const noteAtPitch = (pitch: number): Note => {
  const bounded = Math.max(0, Math.min(MAX_NOTE_PITCH, Math.round(pitch)));
  return `${chromaticNotes[bounded % 12]}${Math.floor(bounded / 12)}` as Note;
};

export const getEditingStep = (melody: Melody, subdivision: Subdivision) =>
  subdivision ? 60000 / getNormalizationOptions(melody).bpm / subdivision : 0;

/** Edit only the requested event. Moving preserves its exact duration; resizing
 * fixes the opposite edge. Times use milliseconds and intervals are [start, end).
 * A free edit can be as short as 1 ms, independently of the visual hit area. */
export const editNote = (
  original: NoteInMelody,
  mode: NoteEditMode,
  deltaMs: number,
  deltaPitch: number,
  step: number,
): NoteInMelody => {
  if (!Number.isFinite(deltaMs) || !Number.isFinite(deltaPitch))
    return original;
  const snap = (time: number) =>
    Math.round(step > 0 ? Math.round(time / step) * step : time);
  const duration = getNoteDuration(original);
  const end = original.start + duration;
  if (mode === 'move') {
    return {
      ...original,
      note: noteAtPitch(notePitch(original.note) + deltaPitch),
      start: deltaMs
        ? Math.max(0, snap(original.start + deltaMs))
        : original.start,
    };
  }
  if (!deltaMs) return original;
  if (mode === 'resize-start') {
    const start = Math.max(
      0,
      Math.min(end - 1, snap(original.start + deltaMs)),
    );
    return { ...original, start, duration: end - start };
  }
  return {
    ...original,
    duration: Math.max(1, snap(end + deltaMs) - original.start),
  };
};
