export const drumSampleOptions = DRUM_SAMPLE_GROUPS.flatMap(group =>
  group.samples.map(option => ({ ...option, group: group.label })),
);

export const getDrumSamplePresentation = (sample: DrumSample) => {
  const artwork =
    sample.kind === 'builtin' ? builtinArtwork[sample.note] : 'custom';
  return {
    label:
      sample.kind === 'custom'
        ? sample.name
        : drumSampleOptions.find(
            option => sampleKey(option.sample) === sampleKey(sample),
          )?.label ?? 'Сохранённый семпл',
    image:
      sample.kind === 'instrument'
        ? instrumentImage(getTimbrePresentation(sample.timbre).artwork)
        : `${process.env.PUBLIC_URL || ''}/images/drum-samples/${artwork}.webp`,
  };
};
