import { Timbre, playNote } from 'app/services/SynthesizerService';

import { Note } from './types';

type PlaybackFilter = (note: Note) => boolean;
let playbackFilter: PlaybackFilter | undefined;

// Filter audio before the attack while retaining input for scoring and keyup.
export const setLiveNotePlaybackFilter = (filter: PlaybackFilter) => {
  playbackFilter = filter;
  return () => {
    if (playbackFilter === filter) playbackFilter = undefined;
  };
};

export const playLiveNote = (timbre: Timbre, note: Note) => {
  if (!playbackFilter || playbackFilter(note)) playNote(timbre, note);
};
