import { GuitarTake } from './capture';

export const encodeGuitarWav = ({
  samples,
  sampleRate,
}: GuitarTake): ArrayBuffer => {
  const buffer = new ArrayBuffer(44 + samples.length * 2);
  const view = new DataView(buffer);
  const text = (offset: number, value: string) => {
    for (let i = 0; i < value.length; i++)
      view.setUint8(offset + i, value.charCodeAt(i));
  };
  text(0, 'RIFF');
  view.setUint32(4, buffer.byteLength - 8, true);
  text(8, 'WAVE');
  text(12, 'fmt ');
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true);
  view.setUint16(22, 1, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * 2, true);
  view.setUint16(32, 2, true);
  view.setUint16(34, 16, true);
  text(36, 'data');
  view.setUint32(40, samples.length * 2, true);
  for (let i = 0; i < samples.length; i++) {
    const value = Math.max(-1, Math.min(1, samples[i]));
    view.setInt16(
      44 + i * 2,
      Math.round(value * (value < 0 ? 32768 : 32767)),
      true,
    );
  }
  return buffer;
};

export const downloadGuitarTake = (take: GuitarTake) => {
  const url = URL.createObjectURL(
    new Blob([encodeGuitarWav(take)], { type: 'audio/wav' }),
  );
  const link = document.createElement('a');
  link.href = url;
  link.download = 'qwertophone-guitar.wav';
  link.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
};
