import { validateImportFile } from './parse';
import { ImportedSong, MelodyImportError } from './types';
import { readInWorker } from './workerClient';

export * from './types';

export const readMusicFile = async (
  file: File,
  signal?: AbortSignal,
): Promise<ImportedSong> => {
  validateImportFile(file.name, file.size);
  const data = await file.arrayBuffer();
  if (signal?.aborted) throw new DOMException('Импорт отменён', 'AbortError');
  if (!window.Worker)
    throw new MelodyImportError(
      'Браузер не поддерживает фоновый импорт. Обновите браузер.',
    );
  const { createImportWorker } = await import('./createWorker');
  if (signal?.aborted) throw new DOMException('Импорт отменён', 'AbortError');
  const worker = createImportWorker();
  return readInWorker(worker, file.name, data, signal);
};
